@kt.kernel
def k(c1=kt.In(8, 32), y=kt.Out(8, 32)):
    s = kt.buffer((8, 32), "f16", name="u1")
    for u in kt.par(1, on=kt.mg):
        kt.zero(4, 32)
    for c in kt.par(2, on=kt.vc):
        kt.store(s[c * 4 : c * 4 + 4, :], kt.load(c1[c * 4 : c * 4 + 4, :]))
    for c in kt.par(2, on=kt.vc):
        kt.store(y[c * 4 : c * 4 + 4, :], kt.load(s[c * 4 : c * 4 + 4, :]))
